1	export function finding(rule, { file, line = null, what, fix, why = null, severity = null }) {
2	  return {
3	    rule: rule.id,
4	    severity: severity || rule.severity,
5	    file,
6	    line,
7	    what,
8	    why: why || rule.why,
9	    fix,
10	    doc: rule.doc,
11	    // The rule's declared creation date, carried onto every finding so the grace
12	    // window below can be applied by the scope-blind reporter, which never sees
13	    // the rules themselves. Undefined on a rule that declared none — see `applyGrace`.
14	    since: rule.since,
15	  };
16	}
17	
18	// HOW LONG A NEW BLOCKING CHECK IS ONLY ADVISORY. A check lands against a tree it
19	// did not grow up with, so its first findings are usually a backlog rather than a
20	// regression — and the run that authored it (a growth capture run, above all) has
21	// neither the scope nor the review to clear that backlog in the same commit.
22	// Without a grace window the only check such a run can land is one the tree already
23	// satisfies, which is the check that proves least; the lesson then lands as prose,
24	// which is the outcome the growth ladder exists to avoid.
25	//
26	// Two weeks is the span in which the backlog is either cleared, the check is
27	// tightened, or the check is deleted as a bad idea — after it, the check bites.
28	export const GRACE_DAYS = 14;
29	
30	const DAY_MS = 24 * 60 * 60 * 1000;
31	
32	// The instant a rule created on `since` starts blocking, or null when it declared
33	// no date or an unparseable one. A rule with no date has no grace: the whole
34	// standing corpus predates this field, and absence must mean "mature", never
35	// "newborn".
36	export function graceUntil(since) {
37	  if (typeof since !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(since)) return null;
38	  const start = Date.parse(`${since}T00:00:00Z`);
39	  return Number.isNaN(start) ? null : new Date(start + GRACE_DAYS * DAY_MS);
40	}
41	
42	// Demote a blocking finding to advisory while its rule is inside its grace window,
43	// recording the date it starts biting so the output says why it did not fail the
44	// build. Runs BEFORE the project's own severity overrides, so a project that has
45	// explicitly set a rule to `blocking` gets what it asked for from day one.
46	//
47	// A `since` in the FUTURE grants nothing: were it honoured, any date far enough out
48	// would disable a blocking check permanently, which is a suppression wearing a
49	// creation date.
50	export function applyGrace(findings, { now = new Date() } = {}) {
51	  return findings.map((f) => {
52	    if (f.severity !== 'blocking') return f;
53	    const until = graceUntil(f.since);
54	    if (!until) return f;
55	    const start = Date.parse(`${f.since}T00:00:00Z`);
56	    if (now < start || now >= until) return f;
57	    return { ...f, severity: 'advisory', graceUntil: until.toISOString().slice(0, 10) };
58	  });
59	}
60	
61	// Severity overrides then acceptances, in that order, so an acceptance is judged
62	// against the rule the project actually runs. A reasonless acceptance is itself
63	// a blocking finding: the reason string is what makes the decision reviewable.
64	export function applyConfig(findings, config) {
65	  const out = [];
66	  for (let f of findings) {
67	    const override = config.rules[f.rule];
68	    if (override === 'advisory' || override === 'blocking') f = { ...f, severity: override };
69	    // A path ending in "/" accepts a whole subtree; otherwise the match is exact.
70	    const acceptance = config.accept.find(
71	      (a) => a.rule === f.rule &&
72	        (!a.path || a.path === f.file || (a.path.endsWith('/') && f.file.startsWith(a.path)))
73	    );
74	    if (acceptance) {
75	      if (typeof acceptance.reason === 'string' && acceptance.reason.trim()) continue;
76	      out.push({
77	        rule: 'config',
78	        severity: 'blocking',
79	        file: '.claudinite-settings.json',
80	        line: null,
81	        what: `acceptance for ${f.rule}${acceptance.path ? ` on ${acceptance.path}` : ''}${acceptance.pack ? ` (on the "${acceptance.pack}" pack entry)` : ''} has no reason`,
82	        why: 'the reason string is what makes an accepted violation reviewable',
83	        fix: 'add a non-empty "reason" to the acceptance entry',
84	        doc: 'engine/checks/README.md',
85	      });
86	    }
87	    out.push(f);
88	  }
89	  return out;
90	}
91	
92	export function render(f) {
93	  const loc = f.line ? `${f.file}:${f.line}` : f.file;
94	  return [
95	    `[${f.severity.toUpperCase()}] ${f.rule}  ${loc}`,
96	    `  ${f.what}`,
97	    ...(f.why ? [`  Why: ${f.why}`] : []),
98	    ...(f.graceUntil ? [`  Grace: added ${f.since} — advisory until ${f.graceUntil}, blocking after`] : []),
99	    `  Fix: ${f.fix}`,
100	    ...(f.doc ? [`  More: ${f.doc}`] : []),
101	  ].join('\n');
102	}
